CREATE OR REPLACE FUNCTION public.cg_format_act_section_html(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v text;
  v_line text;
  v_html text := '';
  v_label text;
  v_body text;
  v_class text;
  v_core text;
  v_prev_kind text := null;
begin
  if p_text is null or btrim(p_text) = '' then
    return '';
  end if;

  -- Display-only whitespace normalization.
  v := regexp_replace(p_text, E'[\\r\\t]+', ' ', 'g');
  v := regexp_replace(v, ' {2,}', ' ', 'g');
  v := btrim(v);

  -- IMPORTANT:
  -- Use chr(10) concatenation instead of replacement strings containing
  -- backreferences such as E'\1' / E'\2'. Those caused the control characters
  -- seen in the previous output.
  --
  -- Insert a newline BEFORE a legal list label where the context shows it is
  -- the start of a list item.

  -- after em/en dash or hyphen
  v := regexp_replace(
    v,
    '([—–-])[[:space:]]+(\([0-9]+[A-Za-z]?\)|\([A-Za-z]{1,4}\))[[:space:]]+',
    '\1' || chr(10) || '\2 ',
    'g'
  );

  -- after semicolon
  v := regexp_replace(
    v,
    ';[[:space:]]*(\([0-9]+[A-Za-z]?\)|\([A-Za-z]{1,4}\))[[:space:]]+',
    ';' || chr(10) || '\1 ',
    'g'
  );

  -- after "; and" / "; or"
  v := regexp_replace(
    v,
    ';[[:space:]]+(and|or)[[:space:]]+(\([0-9]+[A-Za-z]?\)|\([A-Za-z]{1,4}\))[[:space:]]+',
    '; \1' || chr(10) || '\2 ',
    'gi'
  );

  -- numbered subsection after a sentence
  v := regexp_replace(
    v,
    '([.!?])[[:space:]]+(\([0-9]+[A-Za-z]?\))[[:space:]]+',
    '\1' || chr(10) || '\2 ',
    'g'
  );

  -- Existing line breaks remain useful boundaries.
  v := regexp_replace(v, E'\\n+', chr(10), 'g');

  for v_line in
    select btrim(x)
    from regexp_split_to_table(v, E'\\n+') as x
    where btrim(x) <> ''
  loop
    v_label := null;
    v_body := v_line;
    v_class := 'legislation-legal-line';

    if v_line ~ '^\([0-9]+[A-Za-z]?\)[[:space:]]*' then
      v_label := substring(v_line from '^(\([0-9]+[A-Za-z]?\))');
      v_body := regexp_replace(v_line, '^\([0-9]+[A-Za-z]?\)[[:space:]]*', '');
      v_class := v_class || ' legislation-legal-line--subsection';
      v_prev_kind := 'subsection';

    elsif v_line ~ '^\([A-Za-z]{1,4}\)[[:space:]]*' then
      v_label := substring(v_line from '^(\([A-Za-z]{1,4}\))');
      v_body := regexp_replace(v_line, '^\([A-Za-z]{1,4}\)[[:space:]]*', '');
      v_core := lower(trim(both '()' from v_label));

      if v_core in (
        'i','ii','iii','iv','v','vi','vii','viii','ix','x',
        'xi','xii','xiii','xiv','xv','xvi','xvii','xviii','xix','xx'
      ) and v_prev_kind in ('alpha','roman') then
        v_class := v_class || ' legislation-legal-line--roman';
        v_prev_kind := 'roman';
      else
        v_class := v_class || ' legislation-legal-line--alpha';
        v_prev_kind := 'alpha';
      end if;
    else
      v_prev_kind := null;
    end if;

    if v_label is not null then
      v_html := v_html ||
        '<div class="' || v_class || '">' ||
          '<span class="legislation-legal-line__label">' ||
            public.cg_escape_legal_html(v_label) ||
          '</span>' ||
          '<span class="legislation-legal-line__body">' ||
            public.cg_escape_legal_html(v_body) ||
          '</span>' ||
        '</div>';
    else
      v_html := v_html ||
        '<p class="legislation-legal-prose">' ||
          public.cg_escape_legal_html(v_body) ||
        '</p>';
    end if;
  end loop;

  return '<div class="legislation-section-structured">' || v_html || '</div>';
end;
$function$

CREATE OR REPLACE FUNCTION public.cg_format_amendment_html(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v text;
  v_line text;
  v_html text := '';
  v_label text;
  v_body text;
  v_class text;
begin
  if p_text is null or btrim(p_text) = '' then
    return '';
  end if;

  -- Normalize whitespace only for display. The source field remains untouched.
  v := regexp_replace(p_text, E'[\\r\\n\\t]+', ' ', 'g');
  v := regexp_replace(v, E' {2,}', ' ', 'g');
  v := btrim(v);

  -- First item after a dash/colon/semicolon.
  v := regexp_replace(
    v,
    '([—–:;])\s*(\((?:[0-9]+|[a-z]{1,3})\))\s+',
    E'\\1\n\\2 ',
    'gi'
  );

  -- Final item introduced by "and" / "or": preserve the conjunction on the
  -- previous line and move only the legal label to the next line.
  v := regexp_replace(
    v,
    '([,;])\s+(and|or)\s+(\((?:[0-9]+|[a-z]{1,3})\))\s+',
    E'\\1 \\2\n\\3 ',
    'gi'
  );

  -- Subsequent list entries following a semicolon.
  v := regexp_replace(
    v,
    ';\s*(\((?:[0-9]+|[a-z]{1,3})\))\s+',
    E';\n\\1 ',
    'gi'
  );

  -- Numbered subsections following a sentence boundary, e.g.
  -- "... Committee. (2) The Committee..."
  v := regexp_replace(
    v,
    '([.])\s+(\([0-9]+\))\s+',
    E'\\1\n\\2 ',
    'g'
  );

  -- Some extracted source uses a dash immediately before a numbered clause.
  v := regexp_replace(
    v,
    '(-)\s*(\((?:[0-9]+|[a-z]{1,3})\))\s+',
    E'\\1\n\\2 ',
    'gi'
  );

  for v_line in
    select btrim(x)
    from regexp_split_to_table(v, E'\n+') as x
    where btrim(x) <> ''
  loop
    v_label := null;
    v_body := v_line;
    v_class := 'legislation-amendment-line';

    -- Numeric subsection: (1), (2), ...
    if v_line ~ '^\([0-9]+\)\s+' then
      v_label := substring(v_line from '^(\([0-9]+\))');
      v_body := regexp_replace(v_line, '^\([0-9]+\)\s*', '');
      v_class := v_class || ' legislation-amendment-line--subsection';

    -- Roman-number subparagraphs. These are rendered as nested beneath
    -- alphabetic paragraphs, which matches the Schedule's common legal layout.
    elsif lower(v_line) ~ '^\((i|ii|iii|iv|v|vi|vii|viii|ix|x|xi|xii|xiii|xiv|xv)\)\s+' then
      v_label := substring(v_line from '^(\([A-Za-z]+\))');
      v_body := regexp_replace(
        v_line,
        '^\((i|ii|iii|iv|v|vi|vii|viii|ix|x|xi|xii|xiii|xiv|xv)\)\s*',
        '',
        'i'
      );
      v_class := v_class || ' legislation-amendment-line--roman';

    -- Alphabetic / double-letter paragraph: (a), (b), (aa), ...
    elsif lower(v_line) ~ '^\([a-z]{1,3}\)\s+' then
      v_label := substring(v_line from '^(\([A-Za-z]{1,3}\))');
      v_body := regexp_replace(v_line, '^\([A-Za-z]{1,3}\)\s*', '');
      v_class := v_class || ' legislation-amendment-line--alpha';
    end if;

    if v_label is not null then
      v_html := v_html ||
        '<div class="' || v_class || '">' ||
          '<span class="legislation-amendment-line__label">' ||
            public.cg_escape_legal_html(v_label) ||
          '</span>' ||
          '<span class="legislation-amendment-line__body">' ||
            public.cg_escape_legal_html(v_body) ||
          '</span>' ||
        '</div>';
    else
      v_html := v_html ||
        '<p class="legislation-amendment-prose">' ||
          public.cg_escape_legal_html(v_body) ||
        '</p>';
    end if;
  end loop;

  return '<div class="legislation-amendment-structured">' || v_html || '</div>';
end;
$function$

CREATE OR REPLACE FUNCTION public.constituencies_search_vector_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.search_vector := setweight(to_tsvector('english', unaccent(coalesce(NEW.name, ''))), 'A');
  RETURN NEW;
END;
$function$

